import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { LOCALES } from '../i18n/locales';
import { toolsFor } from './registry';

// Share images are generated by `npm run og` (after a build) and committed under public/og/.
const og = (locale: string, name: string) => join(process.cwd(), 'public/og', locale, `${name}.png`);

describe('share images', () => {
  it.each(LOCALES)('%s has a default card and one card per tool', (locale) => {
    const missing = ['default', ...toolsFor(locale).map((t) => t.slug)].filter((name) => !existsSync(og(locale, name)));
    expect(missing, 'run `npm run build && npm run og` and commit public/og').toEqual([]);
  });
});
